use std :: collections :: HashMap ; use std :: fs ; use std :: process :: Command ; use std :: path :: Path ; fn test_zero_values () -> Result < () , String > { let zero_values = vec ! [0 , 0 , 0 , 0 , 0] ; let mut complexity = 0.0 ; complexity += (zero_values [0] as f64 + 1.0) . log10 () * 0.25 ; complexity += (zero_values [1] as f64 + 1.0) . log10 () * 0.15 ; complexity += (zero_values [2] as f64 + 1.0) . log10 () * 0.20 ; complexity += (zero_values [3] as f64 + 1.0) . log10 () * 0.10 ; if zero_values [4] > 0 { complexity += (365.0 / zero_values [4] as f64) . log10 () * 0.10 ; } assert ! (complexity >= 0.0) ; println ! ("    ✓ Zero values test passed") ; Ok (()) }